<script setup>
import { onMounted, reactive, ref } from 'vue'
import { api, money } from '../../api'
import { usePage } from '../../composables/usePage'
import { ElMessage, ElMessageBox } from 'element-plus'
import LoadState from '../../components/LoadState.vue'
const filters = reactive({ keyword: '', status: '' }), { rows, total, page, loading, error, load, search } = usePage('/admin/products', filters)
const dialog = ref(false), saving = ref(false), formError = ref(''), toggling = ref(null), editId = ref(null)
const form = reactive({ name: '', subtitle: '', price: 0, coverUrl: '', description: '', status: 'OFF_SHELF' })
function edit(row) { editId.value = row?.id || null; Object.assign(form, { name: row?.name || '', subtitle: row?.subtitle || '', price: row?.price || 0, coverUrl: row?.coverUrl || '', description: row?.description || '', status: row?.status || 'OFF_SHELF' }); formError.value = ''; dialog.value = true }
async function save() { formError.value = ''; if (!form.name.trim() || Number(form.price) <= 0) { formError.value = '请输入商品名称与大于 0 的价格。'; return }; saving.value = true; try { const payload = { ...form, name: form.name.trim(), price: Number(form.price) }; if (editId.value) await api.put(`/admin/products/${editId.value}`, payload); else await api.post('/admin/products', payload); ElMessage.success('商品已保存'); dialog.value = false; await load() } catch (e) { formError.value = e.message } finally { saving.value = false } }
async function toggle(row) { const status = row.status === 'ON_SALE' ? 'OFF_SHELF' : 'ON_SALE'; try { await ElMessageBox.confirm(`确认${status === 'ON_SALE' ? '上架' : '下架'}「${row.name}」？`, '变更商品状态', { confirmButtonText: '确认', cancelButtonText: '取消' }); toggling.value = row.id; await api.put(`/admin/products/${row.id}`, { name: row.name, subtitle: row.subtitle, price: row.price, coverUrl: row.coverUrl, description: row.description, status }); ElMessage.success('商品状态已更新'); await load() } catch (e) { if (e instanceof Error) ElMessage.error(e.message) } finally { toggling.value = null } }
onMounted(load)
</script>
<template><div class="page-heading"><div><div class="eyebrow">PRODUCT CATALOG</div><h1>商品管理</h1><p>维护商品资料、定价与上架状态。</p></div><el-button type="primary" @click="edit()">＋ 新增商品</el-button></div><section class="surface admin-table-panel"><form class="table-toolbar" @submit.prevent="search"><el-input v-model="filters.keyword" placeholder="搜索商品名称" clearable aria-label="商品名称" @clear="search" /><el-select v-model="filters.status" placeholder="全部状态" clearable aria-label="商品状态" @change="search"><el-option label="已上架" value="ON_SALE" /><el-option label="已下架" value="OFF_SHELF" /></el-select><el-button native-type="submit">查询</el-button><span class="toolbar-count">共 {{ total }} 件</span></form><LoadState :loading="loading" :error="error" :empty="!rows.length" empty-text="没有商品，点击「新增商品」开始" @retry="load"><el-table :data="rows"><el-table-column prop="id" label="ID" width="80" /><el-table-column prop="name" label="商品名称" min-width="180"><template #default="{ row }"><strong>{{ row.name }}</strong><p class="table-subtitle">{{ row.subtitle }}</p></template></el-table-column><el-table-column label="价格" width="120"><template #default="{ row }">¥ {{ money(row.price) }}</template></el-table-column><el-table-column prop="stock" label="可用库存" width="110" /><el-table-column label="状态" width="110"><template #default="{ row }"><el-tag :type="row.status === 'ON_SALE' ? 'success' : 'info'">{{ row.status === 'ON_SALE' ? '已上架' : '已下架' }}</el-tag></template></el-table-column><el-table-column label="操作" min-width="155" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link :type="row.status === 'ON_SALE' ? 'warning' : 'success'" :loading="toggling === row.id" @click="toggle(row)">{{ row.status === 'ON_SALE' ? '下架' : '上架' }}</el-button></template></el-table-column></el-table><el-pagination v-if="total > 15" v-model:current-page="page" :page-size="15" :total="total" layout="total, prev, pager, next" class="pagination" @current-change="load" /></LoadState></section><el-dialog v-model="dialog" :title="editId ? '编辑商品' : '新增商品'" width="580px" :close-on-click-modal="!saving"><el-alert v-if="formError" :title="formError" type="error" :closable="false" show-icon class="form-alert" /><el-form label-position="top" @submit.prevent="save"><el-form-item label="商品名称（必填）"><el-input v-model="form.name" :maxlength="120" /></el-form-item><el-form-item label="简短卖点"><el-input v-model="form.subtitle" :maxlength="200" /></el-form-item><div class="form-two-cols"><el-form-item label="价格（必填）"><el-input-number v-model="form.price" :min="0.01" :max="99999999.99" :precision="2" :step="1" /></el-form-item><el-form-item label="商品状态"><el-select v-model="form.status"><el-option label="已下架" value="OFF_SHELF" /><el-option label="已上架" value="ON_SALE" /></el-select></el-form-item></div><el-form-item label="封面图片 URL"><el-input v-model="form.coverUrl" :maxlength="500" placeholder="https://…（可留空，显示默认封面）" /></el-form-item><el-form-item label="商品描述"><el-input v-model="form.description" type="textarea" :rows="5" :maxlength="10000" /></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存商品</el-button></template></el-dialog></template>
